// Check that RndCnstMsgPerm is a permutation of {0..MsgWidth-1}
// All elements unique and within range
genvar gi, gj;
generate
  for (gi = 0; gi < MsgWidth; gi++) begin : chk_range
    assert property (@(posedge clk_i) disable iff (!rst_ni)
                    (RndCnstMsgPerm[gi] >= 0 && RndCnstMsgPerm[gi] < MsgWidth));
  end
  for (gi = 0; gi < MsgWidth; gi++) begin : chk_uniqueness
    for (gj = gi+1; gj < MsgWidth; gj++) begin : pair
      assert property (@(posedge clk_i) disable iff (!rst_ni)
                      (RndCnstMsgPerm[gi] != RndCnstMsgPerm[gj]));
    end
  end
endgenerate

